def smallest_change(arr):
    def count_changes(arr1, arr2):
        return sum(1 for x, y in zip(arr1, arr2) if x != y)

    n = len(arr)
    mid = n // 2
    first_half = arr[:mid]
    second_half = arr[mid:]
    second_half.reverse()

    return count_changes(first_half, second_half)

